import { readFileSync } from 'node:fs';

const expected = ['market-stand.jpg', 'packing-sheet.png', 'pickup-line.jpg', 'volunteer-badge.jpg'];
const required = ['filename', 'caption', 'tags', 'dominantColors', 'orientation', 'containsText', 'qualityFlags'];
const doc = JSON.parse(readFileSync('index.json', 'utf8'));
if (!Array.isArray(doc.images)) throw new Error('images must be an array');
if (doc.images.length !== expected.length) throw new Error(`expected 4 records, got ${doc.images.length}`);
const names = doc.images.map((row) => row.filename).sort();
if (JSON.stringify(names) !== JSON.stringify(expected)) throw new Error(`filename coverage mismatch: ${names.join(', ')}`);
for (const row of doc.images) {
  for (const field of required) if (!(field in row)) throw new Error(`${row.filename}: missing ${field}`);
  if (typeof row.caption !== 'string' || row.caption.trim().length < 12) throw new Error(`${row.filename}: caption too short`);
  if (!Array.isArray(row.tags) || row.tags.length < 2) throw new Error(`${row.filename}: tags must be an array`);
  if (!Array.isArray(row.dominantColors) || row.dominantColors.length < 2) throw new Error(`${row.filename}: dominantColors must be an array`);
  if (typeof row.containsText !== 'boolean') throw new Error(`${row.filename}: containsText must be boolean`);
  if (!Array.isArray(row.qualityFlags)) throw new Error(`${row.filename}: qualityFlags must be an array`);
}
console.log('INDEX_OK 4/4');
